(97, 'Résidence Lisbon', '44 allée des Tanneurs', 'Lisbon', 'Portugal', 38.736791, -9.158481, 3, '+45390786968', 'Dans un quartier historique prisé, cette maison d''hôtes d''exception cultive l''art de la discrétion et de l''exclusivité. Avec seulement quinze suites, chaque séjour bénéficie d''une attention toute particulière et d''un service sur mesure irréprochable.', 'Bar à cocktails,Bistrot,Salle de sport,Sauna,Bain turc,Conciergerie,Wi-Fi gratuit,Parking', 200),
(98, 'Domaine Baroque', '153 boulevard de la République', 'Edinburgh', 'United Kingdom', 55.934134, -3.194741, 4, '+47585273058', 'Établissement phare de la ville depuis plus d''un siècle, cet hôtel conjugue patrimoine architectural remarquable et confort contemporain. Son histoire, jalonnée d''illustres visiteurs, imprègne chaque recoin de ce lieu chargé d''âme et de prestige.', 'Spa & Bien-être,Piscine intérieure,Restaurant gastronomique,Bar,Salle de fitness,Room service 24h/24,Conciergerie,Parking', 350),
(99, 'Le Château Moderne', '187 impasse des Artisans', 'Hamburg', 'Germany', 53.55592, 9.970897, 5, '+33911488397', 'Établissement phare de la ville depuis plus d''un siècle, cet hôtel conjugue patrimoine architectural remarquable et confort contemporain. Son histoire, jalonnée d''illustres visiteurs, imprègne chaque recoin de ce lieu chargé d''âme et de prestige.', 'Bar à cocktails,Bistrot,Salle de sport,Sauna,Bain turc,Conciergerie,Wi-Fi gratuit,Parking', 143),
(100, 'The Bath', '16 chemin de l''Église', 'Bath', 'United Kingdom', 51.385509, -2.370668, 3, '+49165053034', 'Établissement phare de la ville depuis plus d''un siècle, cet hôtel conjugue patrimoine architectural remarquable et confort contemporain. Son histoire, jalonnée d''illustres visiteurs, imprègne chaque recoin de ce lieu chargé d''âme et de prestige.', 'Piscine extérieure,Spa,Restaurant étoilé,Cave à vins,Jardin privé,Yoga,Parking voiturier', 187);
INSERT INTO hotel_rooms (id, hotel_id, room_type, description, price_per_night, capacity, amenities) VALUES
(1, 1, 'Chambre Classique', 'Chambre confortable de 22 m², décorée avec soin, dotée d''un lit double ou twin, d''une salle de bain privative avec douche, de la climatisation et d''une connexion Wi-Fi haut débit.', 181, 2, 'Wi-Fi,Climatisation,TV,Minibar,Coffre-fort'),
(2, 1, 'Chambre Supérieure', 'Espace de 28 m² rehaussé de touches décoratives élégantes : parquet, moulures, mobilier chiné. Coin salon séparé, nespresso, et accès au club lounge de l''hôtel inclus.', 273, 2, 'Wi-Fi,Climatisation,TV,Minibar,Coffre-fort,Baignoire,Peignoirs'),
(3, 1, 'Chambre Deluxe', 'Chambre premium de 38 m² bénéficiant d''une vue dégagée. Literie cinq étoiles, salle de bain en marbre avec douche à l''italienne et baignoire îlot, plateau de courtoisie garni.', 412, 2, 'Wi-Fi,Climatisation,TV,Minibar,Coffre-fort,Baignoire,Peignoirs,Service en chambre,Nespresso'),
(4, 1, 'Junior Suite', '50 m² de raffinement absolu : dressing privatif, salon avec canapé convertible, salle à manger compacte et salle de bain double vasque avec vue plongeante sur la ville.', 559, 3, 'Wi-Fi,Climatisation,TV,Minibar,Coffre-fort,Baignoire,Peignoirs,Service en chambre,Nespresso,Terrasse,Salon privé'),
(5, 1, 'Suite Royale', 'Suite signature de l''établissement, 120 m² habillés de matériaux nobles — marbre de Carrare, soieries et bois précieux. Service de majordome 24h/24, transfert en limousine et accès au spa privatif.', 3306, 4, 'Wi-Fi,Climatisation,TV,Minibar,Coffre-fort,Baignoire,Peignoirs,Service en chambre,Nespresso,Terrasse,Salon privé,Jacuzzi,Conciergerie dédiée,Majordome,Spa privatif,Transfert limousine'),
